{
  "code": "using System;

public static class Guard
{
    public static bool CanEnterInterview(bool rejected, bool reopenRequested, bool authorized)
    {
        if (rejected && !(reopenRequested && authorized))
            return false;

        return true;
    }
}
",
  "test": "using System;

int pass = 0;
int fail = 0;

void Check(string name, bool actual, bool expected)
{
    if (actual == expected)
    {
        Console.WriteLine($"PASS: {name}");
        pass++;
    }
    else
    {
        Console.WriteLine($"FAIL: {name} (expected {expected}, got {actual})");
        fail++;
    }
}

// Not rejected: always allowed regardless of other flags.
Check("NotRejected_NoReopen_NoAuth", Guard.CanEnterInterview(false, false, false), true);
Check("NotRejected_Reopen_Auth", Guard.CanEnterInterview(false, true, true), true);

// Rejected, no reopen requested: blocked regardless of authorization.
Check("Rejected_NoReopen_NoAuth", Guard.CanEnterInterview(true, false, false), false);
Check("Rejected_NoReopen_Auth", Guard.CanEnterInterview(true, false, true), false);

// Rejected, reopen requested but not authorized: blocked.
Check("Rejected_Reopen_NoAuth", Guard.CanEnterInterview(true, true, false), false);

// Rejected, reopen requested and authorized: allowed (explicit reversal path).
Check("Rejected_Reopen_Auth", Guard.CanEnterInterview(true, true, true), true);

Console.WriteLine($"\n{pass} passed, {fail} failed");
return fail == 0 ? 0 : 1;
",
  "explanation": "The guard blocks direct re-entry into Interviewing for a rejected candidate. A rejected candidate is only allowed back into Interviewing if there is both an explicit reopen request and authorization for that reopen — representing a deliberate, sanctioned exception process rather than an automatic/direct transition. Non-rejected candidates are unaffected by reopenRequested/authorized and always pass.",
  "assumptions": [
    "'Must not go directly back to Interviewing' implies there is an indirect/exception path via reopenRequested + authorized; the ticket does not explicitly describe such a path but the wording 'directly' implies one exists.",
    "Both reopenRequested AND authorized are required together to override the rejection block — authorization alone without an explicit reopen request is not treated as sufficient, and vice versa.",
    "If the candidate is not rejected, reopenRequested and authorized are irrelevant and entry is always allowed (the ticket only constrains the rejected case).",
    "There is no time-based, role-based, or count-based (e.g., max reopen attempts) restriction — the flags given are the only inputs considered.",
    "Authorization is treated as a boolean already validated by the caller (e.g., from a manager approval step) rather than something this guard verifies further.",
    "'Interviewing' here is a single state; no distinction between different interview stages/rounds is made."
  ]
}
